function hydrateHabits(s){
  const t=today();
  s.habits.forEach((h,hi)=>{h.category=h.category||({Água:'Saúde',Leitura:'Desenvolvimento',Academia:'Saúde'}[h.title]||'Bem-estar');h.icon=h.icon||({Água:'💧',Leitura:'📖',Academia:'🏋️'}[h.title]||'◎');h.step=Number(h.step||((h.type==='Duração')?5:((h.unit==='L')?0.25:1)));if(Object.keys(h.logs||{}).length) return; h.logs={}; for(let i=-20;i<=0;i++){const d=addDays(t,i); const weekday=new Date(d+'T12:00:00').getDay(); const base=((i+hi*2)%5!==0); if(h.type==='Check')h.logs[d]=base?1:0; else if(h.unit==='L')h.logs[d]=base?2:1; else h.logs[d]=base?20:5;} });
  for(let i=-10;i<=0;i++){const d=addDays(t,i);if(!s.dayLogs[d])s.dayLogs[d]={mood:['🙂','🙂','😌','😐'][Math.abs(i)%4],energy:['Média','Alta','Média','Baixa'][Math.abs(i)%4],note:'',sleep:7+(i%2)*.5};}
  if(!s.focus.length){for(let i=-8;i<=0;i++){const d=addDays(t,i);s.focus.push({id:uid()+i,date:d,minutes:Math.max(20,80+(i%4)*20),area:i%3===0?'Vida':'Faculdade'});}}
  return s;
}

function load(){try{let x=localStorage.getItem(KEY);if(!x){for(const k of LEGACY_KEYS){x=localStorage.getItem(k);if(x)break}}if(x)return normalize(JSON.parse(x));}catch(e){}return hydrateHabits(seed())}
function normalize(raw){const base=seed();const s={...base,...raw,settings:{...base.settings,...raw.settings},ui:{...base.ui,...raw.ui}};if(['Meu NEXO','Meu AEVRYA','Meu AUVRYN'].includes(String(s.settings.name||'')))s.settings.name='Meu AUVRYN';['tasks','events','projects','habits','summaries','exams','questionLogs','assignments','materials','academicFiles','health','workouts','workoutExercises','workoutSessions','purchases','trips','library','flashcardDecks','flashcards','finances','documents','people','goals','journal','focus'].forEach(k=>s[k]=raw[k]||base[k]);s.dayLogs=raw.dayLogs||{};return hydrateHabits(s)}
