function setSelectedDate(d){state.ui.selectedDate=d;save();render()}
function byId(arr,id){return arr.find(x=>String(x.id)===String(id))}
function pct(n,d){return d?Math.round(n/d*100):0}
function isDone(t){return t.status==='Concluída'}
function taskScore(date){const a=state.tasks.filter(t=>t.date===date);return pct(a.filter(isDone).length,a.length)}
function habitDone(h,date){const v=Number(h.logs?.[date]||0);return v>=Number(h.target||1)}
function habitScore(date){return pct(state.habits.filter(h=>habitDone(h,date)).length,state.habits.length)}
function focusFor(date){return state.focus.filter(x=>x.date===date).reduce((a,b)=>a+Number(b.minutes||0),0)}
function qFor(date){return state.questionLogs.filter(x=>x.date===date).reduce((a,b)=>a+Number(b.count||0),0)}
function dayScore(date){const ts=taskScore(date),hs=habitScore(date);const study=Math.min(100,Math.round((focusFor(date)/90)*100));return Math.round(ts*.35+hs*.35+study*.3)}
function weekDates(center=selectedDate()){const d=new Date(center+'T12:00:00');const day=(d.getDay()+6)%7;d.setDate(d.getDate()-day);return Array.from({length:7},(_,i)=>{const x=new Date(d);x.setDate(d.getDate()+i);return iso(x)})}
function monthDates(date=selectedDate()){const base=new Date(date+'T12:00:00');const first=new Date(base.getFullYear(),base.getMonth(),1,12);const start=new Date(first);start.setDate(1-((first.getDay()+6)%7));return Array.from({length:42},(_,i)=>{const x=new Date(start);x.setDate(start.getDate()+i);return iso(x)})}

