function hexOk(v){return /^#[0-9a-f]{6}$/i.test(String(v||''))}
function hexRgb(hex){hex=String(hex).replace('#','');return [0,2,4].map(i=>parseInt(hex.slice(i,i+2),16))}
function rgbHex(rgb){return '#'+rgb.map(x=>Math.max(0,Math.min(255,Math.round(x))).toString(16).padStart(2,'0')).join('')}
function mixHex(a,b,t){const x=hexRgb(a),y=hexRgb(b);return rgbHex(x.map((v,i)=>v+(y[i]-v)*t))}
function colorLum(hex){const c=hexRgb(hex).map(v=>v/255).map(v=>v<=.03928?v/12.92:((v+.055)/1.055)**2.4);return .2126*c[0]+.7152*c[1]+.0722*c[2]}
function accentPalette(input){
  let base=hexOk(input)?input.toLowerCase():'#6f5bd3',dark=state.settings.theme==='dark';
  const display=dark&&colorLum(base)<.28?mixHex(base,'#ffffff',.28):base;
  return dark?{base:display,soft:mixHex(display,'#171715',.68),faint:mixHex(display,'#171715',.84),deep:mixHex(display,'#000000',.24),ink:mixHex(display,'#ffffff',.26),on:colorLum(display)>.42?'#161514':'#ffffff'}:{base,soft:mixHex(base,'#ffffff',.82),faint:mixHex(base,'#ffffff',.94),deep:mixHex(base,'#000000',.18),ink:mixHex(base,'#000000',.38),on:colorLum(base)>.45?'#1c1a17':'#ffffff'};
}
function applyAccent(){
  const root=document.documentElement,a=hexOk(state.settings.accent)?state.settings.accent:'#6f5bd3',p=accentPalette(a);
  [root,document.body].forEach(el=>{el.style.setProperty('--accent',p.base);el.style.setProperty('--accent-soft',p.soft);el.style.setProperty('--accent-faint',p.faint);el.style.setProperty('--accent-deep',p.deep);el.style.setProperty('--accent-ink',p.ink);el.style.setProperty('--on-accent',p.on)});
  document.querySelector('meta[name="theme-color"]')?.setAttribute('content',state.settings.theme==='dark'?'#171715':p.faint);
}
