function defaultFor(type){const d=selectedDate();const map={task:{title:'',area:'Vida',date:d,time:'',duration:20,energy:'Média',priority:'Média',status:'Pendente',projectId:'',postponedCount:0,lastPostponedAt:'',notes:''},event:{title:'',date:d,start:'09:00',end:'10:00',category:'Pessoal',notes:''},project:{title:'',area:'Pessoal',status:'Planejando',progress:0,due:addDays(d,30),notes:''},habit:{title:'',icon:'◎',category:'Bem-estar',type:'Check',target:1,unit:'feito',minimum:1,step:1,frequency:5,logs:{}},summary:{title:'',period:state.ui.academicPeriod||'1º',discipline:'',subject:'',confidence:'Média',favorite:false,updated:d,lastReview:d,questions:0,accuracy:0,content:''},exam:{title:'',period:'',discipline:'',date:addDays(d,14),time:'',progress:0,importance:'Média',notes:''},questionLog:{date:d,discipline:'',subject:'',count:20,correct:0},assignment:{title:'',period:'',discipline:'',date:addDays(d,7),time:'',status:'Não iniciado',progress:0,notes:''},material:{title:'',period:state.ui.academicPeriod||'1º',discipline:'',kind:'PDF',location:'',notes:''},health:{title:'',type:'Consulta',date:d,value:'',notes:''},workout:{title:'',goal:'Hipertrofia',days:'3x por semana',duration:60,status:'Ativo',notes:''},workoutExercise:{workoutId:state.workouts[0]?.id||'',order:state.workoutExercises.length+1,name:'',sets:3,reps:'8–12',load:'',rest:'90 s',notes:''},workoutSession:{workoutId:state.workouts[0]?.id||'',date:d,duration:60,rating:'Bom',notes:''},academicFile:{name:'',period:'',discipline:'',summaryId:'',notes:''},purchase:{title:'',price:0,priority:'Média',status:'Planejando',target:addDays(d,30),notes:''},trip:{title:'',destination:'',start:addDays(d,30),end:addDays(d,37),budget:0,status:'Ideias',notes:''},library:{type:state.ui.libraryType||'book',title:'',creator:'',status:'Quero',progress:0,rating:0,meta:'',coverKey:'',coverUrl:'',coverCloudPath:'',notes:''},flashcardDeck:{title:'',discipline:'',subject:'',createdAt:d},flashcard:{deckId:state.flashcardDecks[0]?.id||'',front:'',back:'',tags:'',interval:1,nextReview:d,streak:0},finance:{title:'',type:'Despesa',amount:0,date:d,category:'',notes:''},document:{title:'',category:'Pessoal',expires:'',location:'',notes:''},person:{name:'',relation:'',birthday:'',lastContact:d,notes:''},goal:{title:'',area:'Pessoal',progress:0,due:addDays(d,90),notes:''},journal:{date:d,title:'',mood:'🙂',energy:'Média',content:''},dayLog:{mood:'🙂',energy:'Média',sleep:7,note:''}};return map[type]}
function getEntity(type,id){const sc=schemas[type];if(type==='dayLog')return state.dayLogs[id]||defaultFor(type);return byId(state[sc.collection],id)}
function openEditor(type,id=null){const sc=schemas[type];if(!sc)return;const isEdit=id!==null&&id!==undefined;const obj=isEdit?getEntity(type,id):defaultFor(type);$('#editorEyebrow').textContent=isEdit?'Editar':'Criar';$('#editorTitle').textContent=sc.title;$('#editorDelete').classList.toggle('hidden',!isEdit||type==='dayLog');$('#editorDelete').dataset.type=type;$('#editorDelete').dataset.id=id||'';$('#editorForm').dataset.type=type;$('#editorForm').dataset.id=id||'';$('#editorFields').innerHTML=sc.fields.map(f=>fieldHtml(f,obj)).join('');if(type==='library'&&isEdit){const hasImage=!!(obj.coverKey||obj.coverUrl);$('#editorFields').insertAdjacentHTML('beforeend',`<div class="library-image-manager"><div><b>Imagem do item</b><small>${hasImage?'A capa fica limpa na estante. Troque ou remova somente aqui.':'Você pode adicionar uma capa se quiser. É opcional.'}</small></div><div class="library-image-manager-actions"><button class="secondary-btn compact" type="button" id="editorLibraryImage">${hasImage?'Trocar imagem':'＋ Adicionar imagem'}</button>${hasImage?'<button class="danger-btn compact" type="button" id="editorLibraryImageRemove">Remover imagem</button>':''}</div></div>`)}$('#editorDialog').showModal();if(type==='library'&&isEdit){const add=$('#editorLibraryImage'),rem=$('#editorLibraryImageRemove');if(add)add.onclick=()=>pickLibraryCover(id);if(rem)rem.onclick=()=>removeLibraryCover(id)}}
function fieldHtml([key,label,type,opts],obj){const v=obj?.[key]??'';if(type==='textarea')return `<div class="field"><label>${label}</label><textarea class="textarea" name="${key}">${esc(v)}</textarea></div>`;if(type==='select'){const choices=typeof opts==='function'?opts():opts;return `<div class="field"><label>${label}</label><select class="select" name="${key}">${choices.map(o=>{const pair=Array.isArray(o),val=pair?o[0]:o,txt=pair?o[1]:o;return `<option value="${esc(val)}" ${String(v)===String(val)?'selected':''}>${esc(txt)}</option>`}).join('')}</select></div>`}if(type==='checkbox')return `<div class="field"><label>${label}</label><label><input type="checkbox" name="${key}" ${v?'checked':''}> Sim</label></div>`;return `<div class="field"><label>${label}</label><input class="input" type="${type}" name="${key}" value="${esc(v)}"></div>`}
$('#editorForm').onsubmit=e=>{e.preventDefault();const type=e.currentTarget.dataset.type,id=e.currentTarget.dataset.id||null,sc=schemas[type],fd=new FormData(e.currentTarget),obj=id?{...getEntity(type,id)}:{id:uid(),...defaultFor(type)};sc.fields.forEach(([k,,t])=>{obj[k]=t==='checkbox'?fd.get(k)==='on':t==='number'?Number(fd.get(k)||0):fd.get(k)||''});if(type==='library'&&obj.coverUrl&&!/^https:\/\//i.test(obj.coverUrl))return toast('A URL da imagem precisa usar HTTPS');if(type==='habit'&&!obj.logs)obj.logs={};if(type==='flashcard'){obj.interval=Number(obj.interval||1);obj.nextReview=obj.nextReview||today();obj.streak=Number(obj.streak||0)}if(type==='flashcardDeck')obj.createdAt=obj.createdAt||today();if(type==='dayLog')state.dayLogs[id]=obj;else if(id){const arr=state[sc.collection],idx=arr.findIndex(x=>String(x.id)===String(id));arr[idx]=obj}else state[sc.collection].push(obj);save();$('#editorDialog').close();render();toast(id?'Alterações salvas':'Item criado')}
$('#editorDelete').onclick=()=>{const {type,id}=$('#editorDelete').dataset;$('#editorDialog').close();if(type==='academicFile'){deleteAcademicFile(id);return}askDelete(type,id)};
function askDelete(type,id){pendingDelete={type,id};const sc=schemas[type];$('#confirmTitle').textContent=`Excluir ${sc?.title?.toLowerCase()||'item'}?`;$('#confirmText').textContent='Essa ação remove o item deste navegador.';$('#confirmDialog').showModal()}
$('#confirmOk').onclick=()=>{if(!pendingDelete)return;const {type,id}=pendingDelete,sc=schemas[type];if(sc){if(type==='workout'){state.workoutExercises=state.workoutExercises.filter(x=>String(x.workoutId)!==String(id));state.workoutSessions=state.workoutSessions.filter(x=>String(x.workoutId)!==String(id))}if(type==='flashcardDeck')state.flashcards=state.flashcards.filter(x=>String(x.deckId)!==String(id));if(type==='library'){const it=byId(state.library,id);if(it?.coverKey)removeFileBlob(it.coverKey).catch(()=>{});if(it?.coverCloudPath)deleteCloudBlob(it.coverCloudPath).catch(()=>{})}if(type==='summary')state.academicFiles.forEach(x=>{if(String(x.summaryId)===String(id))x.summaryId='' });state[sc.collection]=state[sc.collection].filter(x=>String(x.id)!==String(id));save();setTimeout(render,0);toast('Item excluído')}pendingDelete=null};

function bindSettings(){
 const name=$('#settingsName'),course=$('#settingsCourse'),inst=$('#settingsInstitution'),periodCount=$('#settingsPeriodCount');
 if(name)name.onchange=e=>{state.settings.name=e.target.value||'Meu AUVRYN';const a=authRecord();if(a){a.name=state.settings.name;localStorage.setItem(AUTH_KEY,JSON.stringify(a))}save();render()};
 if(course)course.onchange=e=>{state.settings.course=e.target.value.trim()||'Meu curso';save();render()};if(inst)inst.onchange=e=>{state.settings.institution=e.target.value.trim();save();render()};
 if(periodCount)periodCount.onchange=e=>{state.settings.periodCount=clamp(Number(e.target.value)||1,1,20);save();render()};const spa=$('#settingsPeriodAuto');if(spa)spa.onclick=()=>{state.settings.periodCount=0;save();render();toast(`AUVRYN ajustou para ${academicPeriodCount()} períodos`)};
 const st=$('#settingsTheme');if(st)st.onclick=()=>{state.settings.theme=state.settings.theme==='dark'?'light':'dark';save();render()};const pr=$('#protectRest');if(pr)pr.onclick=()=>{state.settings.protectRest=!state.settings.protectRest;save();render()};
 $$('[data-accent]').forEach(b=>b.onclick=()=>{state.settings.accent=b.dataset.accent;save();applyAccent();render();toast('Cor aplicada em todo o AUVRYN')});const ca=$('#customAccent');if(ca){ca.oninput=e=>{state.settings.accent=e.target.value;applyAccent()};ca.onchange=e=>{state.settings.accent=e.target.value;save();render();toast('Cor personalizada aplicada')}};
 const hm=$('#heroMode');if(hm)hm.onchange=e=>{state.settings.heroMode=e.target.value;save();render()};const hu=$('#heroImageUrl');if(hu)hu.onchange=e=>{const v=e.target.value.trim();if(v&&!/^https:\/\//i.test(v))return toast('Use uma URL HTTPS para a imagem');state.settings.heroImageUrl=v;state.settings.heroMode=v?'url':'generated';save();render()};const hf=$('#heroImageFile');if(hf)hf.onchange=e=>pickHeroImage(e.target.files?.[0]);const hc=$('#clearHeroImage');if(hc)hc.onclick=clearHeroImage;
 const out=$('#exportData');if(out)out.onclick=exportData;const inp=$('#importData');if(inp)inp.onchange=importData;const es=$('#exportAllSummaries');if(es)es.onclick=exportAllSummariesMarkdown;const ew=$('#exportAllWorkouts');if(ew)ew.onclick=exportAllWorkouts;const af=$('#downloadAllAcademicFiles');if(af)af.onclick=()=>downloadAllAcademicFiles();const lc=$('#downloadLibraryCovers');if(lc)lc.onclick=()=>downloadAllLibraryCovers();const lo=$('#logoutBtn');if(lo)lo.onclick=logoutLocalAccount;const rv=$('#resendVerification');if(rv)rv.onclick=resendVerification;
 const cs=$('#cloudSyncNow');if(cs)cs.onclick=()=>pushCloudState('manual',true);const cp=$('#cloudPullNow');if(cp)cp.onclick=()=>pullCloudState(true);
 const reset=$('#resetData');if(reset)reset.onclick=()=>{if(confirm('Restaurar os dados de demonstração?')){state=hydrateHabits(seed());save();render();toast('Demonstração restaurada')}};hydrateHeroImage(true).catch(()=>{});
}
function exportData(){const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`auvryn-backup-${today()}.json`;a.click();URL.revokeObjectURL(url)}
function importData(e){const f=e.target.files?.[0];if(!f)return;const r=new FileReader();r.onload=()=>{try{state=normalize(JSON.parse(r.result));save();render();toast('Backup importado')}catch(err){toast('Arquivo inválido')}};r.readAsText(f)}

let focusTimer=null,focusRemaining=25*60,focusStarted=false;
function focusText(){const m=Math.floor(focusRemaining/60),sec=focusRemaining%60;const el=$('#focusClock');if(el)el.textContent=`${String(m).padStart(2,'0')}:${String(sec).padStart(2,'0')}`}
function openFocus(){focusRemaining=25*60;focusStarted=false;focusText();$('#focusToggle').textContent='Iniciar';$('#focusDialog').showModal()}
function stopFocus(saveLog=false){if(focusTimer){clearInterval(focusTimer);focusTimer=null}if(saveLog){const used=Math.max(1,25-Math.ceil(focusRemaining/60));state.focus.push({id:uid(),date:selectedDate(),minutes:used,area:'Faculdade'});save();toast(`${used} min de foco registrados`)}focusStarted=false}
$('#focusToggle').onclick=()=>{if(focusStarted){stopFocus(true);$('#focusToggle').textContent='Iniciar';return}focusStarted=true;$('#focusToggle').textContent='Pausar';focusTimer=setInterval(()=>{focusRemaining--;focusText();if(focusRemaining<=0){stopFocus(false);state.focus.push({id:uid(),date:selectedDate(),minutes:25,area:'Faculdade'});save();$('#focusToggle').textContent='Concluído';toast('Sessão de foco concluída')}},1000)};
$('#focusReset').onclick=()=>{stopFocus(false);focusRemaining=25*60;focusText();$('#focusToggle').textContent='Iniciar'};$('#focusClose').onclick=()=>{if(focusStarted)stopFocus(true);$('#focusDialog').close()};

function globalSearch(q){q=q.trim().toLowerCase();if(!q)return[];const out=[];const add=(type,icon,arr,name,meta)=>arr.forEach(x=>{const text=JSON.stringify(x).toLowerCase();if(text.includes(q))out.push({type,icon,id:x.id,title:name(x),meta:meta(x)})});add('task','✓',state.tasks,x=>x.title,x=>`${x.area} · ${x.date}`);add('summary','⌁',state.summaries,x=>x.title,x=>`${x.period} · ${x.discipline}`);add('flashcardDeck','◫',state.flashcardDecks,x=>x.title,x=>`${x.discipline||'Flashcards'} · ${state.flashcards.filter(c=>String(c.deckId)===String(x.id)).length} cartões`);add('flashcard','□',state.flashcards,x=>x.front,x=>byId(state.flashcardDecks,x.deckId)?.title||'Flashcard');add('project','◎',state.projects,x=>x.title,x=>x.area);add('library','▤',state.library,x=>x.title,x=>x.creator||x.meta);add('journal','✎',state.journal,x=>x.title,x=>x.date);add('person','♡',state.people,x=>x.name,x=>x.relation);add('workout','↟',state.workouts,x=>x.title,x=>`${x.goal} · ${x.days}`);add('academicFile','▧',state.academicFiles,x=>x.name,x=>`${x.discipline||'Arquivo'} · ${prettySize(x.size)}`);add('exam','◈',state.exams,x=>x.title,x=>`${x.discipline||'Avaliação'} · ${x.date||''}`);add('assignment','◇',state.assignments,x=>x.title,x=>`${x.discipline||'Trabalho'} · ${x.date||''}`);add('material','↗',state.materials,x=>x.title,x=>`${x.discipline||'Material'} · ${x.kind||''}`);return out.slice(0,40)}
function openSearch(){const d=$('#searchDialog');d.showModal();$('#globalSearch').value='';$('#searchResults').innerHTML='<div class="empty">Digite para buscar tarefas, resumos, PDFs, avaliações, materiais, projetos, cultura, pessoas e diário.</div>';setTimeout(()=>$('#globalSearch').focus(),50)}
$('#globalSearch').oninput=e=>{const arr=globalSearch(e.target.value);$('#searchResults').innerHTML=arr.length?arr.map(x=>`<button class="search-result" data-search-type="${x.type}" data-search-id="${x.id}"><span>${x.icon}</span><div><b>${esc(x.title)}</b><small>${esc(x.meta||'')}</small></div></button>`).join(''):'<div class="empty">Nada encontrado.</div>';$$('[data-search-type]').forEach(b=>b.onclick=()=>{const t=b.dataset.searchType,id=b.dataset.searchId;$('#searchDialog').close();if(t==='summary')go('academics/summary/'+id);else if(t==='flashcardDeck')go('academics/flashcards/'+id);else openEditor(t,id)})};$('#searchClose').onclick=()=>$('#searchDialog').close();

$('#searchTrigger').onclick=openSearch;$('#themeBtn').onclick=()=>{state.settings.theme=state.settings.theme==='dark'?'light':'dark';save();render()};$('#globalAdd').onclick=$('#headerAdd').onclick=()=>{if(typeof window.openAuvrynCapture==='function')window.openAuvrynCapture();else openEditor('task')};$('#mobileMenu').onclick=()=>document.body.classList.add('menu-open');$('#sidebarClose').onclick=()=>document.body.classList.remove('menu-open');$('#profileAccountBtn').onclick=openAccountDialog;$('#accountDialogClose').onclick=()=>$('#accountDialog').close();$('#accountLogoutBtn').onclick=logoutLocalAccount;$('#accountSwitchBtn').onclick=logoutLocalAccount;
