window.addEventListener('hashchange',()=>{if(!document.body.classList.contains('auth-locked'))render()});document.addEventListener('keydown',e=>{if(document.body.classList.contains('auth-locked'))return;if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();openSearch()}if(!e.metaKey&&!e.ctrlKey&&e.key.toLowerCase()==='n'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)){e.preventDefault();if(typeof window.openAuvrynCapture==='function')window.openAuvrynCapture();else openEditor('task')}if(e.key==='Escape')document.body.classList.remove('menu-open')});
